SELECT id, interval_code, UNIX_TIMESTAMP(candle_open_time) AS candle_epoch, UNIX_TIMESTAMP(generated_at) AS gen_epoch, UNIX_TIMESTAMP(created_at) AS created_epoch, decision, original_decision, total_score, trend_score, momentum_score, volume_score, atr_entry_type, atr_immediate_entry_allowed FROM crypto_ai.trade_signal WHERE symbol='EGLDUSDT' AND generated_at BETWEEN FROM_UNIXTIME(1791747595) AND FROM_UNIXTIME(1791747840) ORDER BY generated_at LIMIT 30;